formData.jsFunction:
def validate(request, response = [:]) {

    if (request.containsKey("mapJson")) {
        def mapJSON = request.mapJson
        if (!(mapJSON.containsKey("dir") || mapJSON.containsKey("temp_uuid"))) {
            response.dir = "The required dir/temp-uuid in the formData is missing"
        }
        if (mapJSON.containsKey("efwd")) {
            def efwdJson = mapJSON.efwd
            def efwdFileName = (efwdJson.containsKey("file") && efwdJson.file != null) ? efwdJson.file : null
            if (efwdFileName == null) {
                response.efwd = "The required file in the efwd in formData is missing"
            } else if (efwdFileName.isEmpty()) {
                response.efwd = "The required file in the efwd in formData cannot be empty"
            }
        }
    } else {
        response.mapJson = "The required mapJson in the formData is missing"
    }
    return response

}
